import torch

_DTYPES = {
    "float16": torch.float16,
    "float32": torch.float32,
    "float64": torch.float64,
    "bfloat16": torch.bfloat16,
    "int8": torch.int8,
    "uint8": torch.uint8,
    "int16": torch.int16,
    "int32": torch.int32,
    "int64": torch.int64,
}


def _to_dtype(dt):
    if isinstance(dt, str):
        return _DTYPES[dt]
    return dt


def _tensor(data, dtype, device):
    if dtype.is_floating_point:
        return torch.tensor(data, dtype=dtype, device=device)
    return torch.tensor(data, dtype=torch.int64, device="cpu").to(dtype).to(device)


def gen_inputs(ctx, device):
    dtype = _to_dtype(ctx["sorted_sequence__dtype"])
    seq_shape = tuple(ctx["sorted_sequence__shape"])
    if seq_shape == (5,):
        sorted_sequence = _tensor([0, 2, 2, 5, 9], dtype, device)
        values = _tensor([[0, 1, 2], [3, 9, 10]], dtype, device)
    elif seq_shape == (2, 5):
        sorted_sequence = _tensor([[0, 2, 2, 5, 9], [1, 3, 4, 4, 8]], dtype, device)
        values = _tensor([[0, 2, 6], [1, 4, 9]], dtype, device)
    elif seq_shape == (2, 2, 4):
        sorted_sequence = _tensor(
            [[[0, 2, 2, 5], [1, 3, 4, 8]], [[2, 4, 6, 6], [0, 1, 7, 9]]], dtype, device
        )
        values = _tensor(
            [[[0, 2, 6], [2, 4, 9]], [[1, 5, 7], [0, 8, 10]]], dtype, device
        )
    elif seq_shape == (2, 3):
        sorted_sequence = _tensor([[0, 2, 4], [1, 3, 5]], dtype, device)
        values = torch.empty((2, 0), dtype=dtype, device=device)
    elif seq_shape == (2, 0):
        sorted_sequence = torch.empty((2, 0), dtype=dtype, device=device)
        values = _tensor([[0, 2], [1, 3]], dtype, device)
    else:
        raise AssertionError(f"unknown seq shape {seq_shape}")
    return {"sorted_sequence": sorted_sequence, "values": values}


def run(sorted_sequence, values, out_int32, right, side):
    return torch.searchsorted(
        sorted_sequence, values, out_int32=out_int32, right=right, side=side
    )
